function FootnoteStar() {
  return (
    <motion.span
      aria-hidden="true"
      initial={{ scale: 0, rotate: -40 }}
      whileInView={{ scale: 1, rotate: 0 }}
      viewport={{ once: true }}
      transition={{ type: "spring", stiffness: 260, damping: 14, delay: 0.25 }}
      style={{
        position: "absolute",
        zIndex: -1,
        width: "0.62em",
        height: "0.62em",
        left: "-0.78em",
        top: "0.12em",
        pointerEvents: "none",
      }}
    >
      <svg
        viewBox="0 0 100 100"
        className="footnote-star-spin"
        style={{ display: "block", width: "100%", height: "100%", overflow: "visible" }}
      >
        <path d={FOOTNOTE_STAR_PATH} fill={COLORS.accent2} stroke={COLORS.accent2} strokeWidth="5" strokeLinejoin="round" />
      </svg>
    </motion.span>
  );
}

