function About() {
  const [expanded, setExpanded] = useState(false);

  return (
    <section id="about" className="px-6 py-16 md:py-20">
      <div className="max-w-2xl mx-auto">
        <motion.h2
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="font-inter section-heading text-3xl md:text-4xl text-center mb-14 md:mb-16"
          style={{ color: COLORS.ink }}
        >
          <span className="relative inline-block">
            About me
            <span className="absolute left-0 top-full w-full" style={{ marginTop: "2px" }}>
              <UnderlineDoodle />
            </span>
          </span>
        </motion.h2>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.1 }}
        >
          <p
            className="font-body font-bold text-lg md:text-xl mb-4"
            style={{ color: "#000000" }}
          >
            Hi, I'm Simge.
          </p>
          <p
            className="font-body text-[15px] md:text-base leading-relaxed"
            style={{ color: "#000000" }}
          >
            My journey began with three years of full-time experience in
            graphic design, where I worked on marketing visuals, social media
            content, and a variety of production projects.
          </p>

          <AnimatePresence initial={false}>
            {expanded && (
              <motion.div
                key="more"
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: "auto", opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.4, ease: "easeInOut" }}
                className="overflow-hidden"
              >
                <p
                  className="font-body text-[15px] md:text-base leading-relaxed mt-4"
                  style={{ color: "#000000" }}
                >
                  Over time, I found myself increasingly drawn to motion and
                  animation. This led me to transition into freelance motion
                  design, where I now focus on creating visuals that combine
                  design, movement, and storytelling.
                </p>
                <p
                  className="font-body text-[15px] md:text-base leading-relaxed mt-4"
                  style={{ color: "#000000" }}
                >
                  My background in graphic design continues to shape the way
                  I approach motion, helping me bring together strong visual
                  fundamentals and purposeful animation to create work that
                  is both visually engaging and clear in its communication.
                </p>
              </motion.div>
            )}
          </AnimatePresence>

          <button
            onClick={() => setExpanded((e) => !e)}
            className="mt-4 font-body font-bold text-sm underline-grow"
            style={{ color: COLORS.ink }}
          >
            {expanded ? "Show less" : "Read more"}
          </button>
        </motion.div>
      </div>
    </section>
  );
}

