function Testimonials() {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const t = setInterval(() => {
      setIndex((i) => (i + 1) % TESTIMONIALS.length);
    }, 5500);
    return () => clearInterval(t);
  }, []);

  return (
    <section className="px-6 py-16 md:py-20">
      <div className="max-w-3xl mx-auto text-center">
        <motion.h2
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="font-inter section-heading text-3xl md:text-4xl mb-14 md:mb-16"
          style={{ color: COLORS.ink }}
        >
          <span className="relative inline-block">
            Kind words
            <span className="absolute left-0 top-full w-full" style={{ marginTop: "2px" }}>
              <UnderlineDoodle />
            </span>
          </span>
        </motion.h2>

        <div
          className="relative rounded-3xl p-8 md:p-12 min-h-[220px] flex items-center justify-center overflow-hidden"
          style={{ backgroundColor: `${COLORS.accent2}1F` }}
        >
          <AnimatePresence mode="wait">
            <motion.div
              key={index}
              initial={{ opacity: 0, x: 24 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -24 }}
              transition={{ duration: 0.45, ease: "easeOut" }}
            >
              <p
                className="font-body text-base md:text-lg leading-relaxed mb-6"
                style={{ color: "#000000" }}
              >
                "{TESTIMONIALS[index].quote}"
              </p>
              <p
                className="font-body font-bold text-sm"
                style={{ color: COLORS.ink }}
              >
                {TESTIMONIALS[index].name}
              </p>
              {TESTIMONIALS[index].role && (
                <p
                  className="font-body text-xs"
                  style={{ color: `${COLORS.ink}99` }}
                >
                  {TESTIMONIALS[index].role}
                </p>
              )}
            </motion.div>
          </AnimatePresence>
        </div>

        <div className="flex justify-center gap-2 mt-7 flex-wrap">
          {TESTIMONIALS.map((_, i) => (
            <button
              key={i}
              aria-label={`Show testimonial ${i + 1}`}
              onClick={() => setIndex(i)}
              className="h-2 rounded-full transition-all"
              style={{
                width: i === index ? "22px" : "8px",
                backgroundColor: i === index ? COLORS.ink : `${COLORS.ink}33`,
              }}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

/* ---------------------------------------------
   CONTACT FORM
--------------------------------------------- */
function ContactForm() {
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [sent, setSent] = useState(false);
  const CONTACT_EMAIL = "sembolstudio@gmail.com";

  function handleSubmit(e) {
    e.preventDefault();
    const subject = encodeURIComponent(`Project inquiry from ${form.name}`);
    const body = encodeURIComponent(
      `Name: ${form.name}\nEmail: ${form.email}\n\n${form.message}`
    );
    window.location.href = `mailto:${CONTACT_EMAIL}?subject=${subject}&body=${body}`;
    setSent(true);
    setTimeout(() => setSent(false), 3500);
    setForm({ name: "", email: "", message: "" });
  }

  const inputStyle = {
    backgroundColor: "#FFFFFF",
    border: `1px solid ${COLORS.ink}26`,
    color: COLORS.ink,
  };

  return (
    <section id="contact" className="contact-section px-6 pb-24 md:pb-32">
      <div className="max-w-xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="heart-snap mx-auto"
          aria-hidden="true"
        >
          <HandLottie animationData={LOTTIE_HEART_SNAP} />
        </motion.div>
        <motion.h2
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="font-inter section-heading text-3xl md:text-4xl text-center mb-12 md:mb-14"
          style={{ color: COLORS.ink }}
        >
          Let's{" "}
          <span className="relative inline-block">
            talk
            <span className="absolute left-0 top-full w-full" style={{ marginTop: "2px" }}>
              <UnderlineDoodle />
            </span>
          </span>
        </motion.h2>
        <motion.p
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.1 }}
          className="font-body text-center mb-12"
          style={{
            color: "#000000",
            fontSize: "clamp(16px, 5vw, 18px)",
            fontWeight: 500,
          }}
        >
          Tell me about your project
        </motion.p>

        <motion.form
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.15 }}
          onSubmit={handleSubmit}
          className="flex flex-col gap-4"
        >
          <input
            required
            type="text"
            placeholder="Name"
            value={form.name}
            onChange={(e) => setForm({ ...form, name: e.target.value })}
            className="font-body text-sm rounded-xl px-4 py-3.5 outline-none transition-shadow focus:ring-2"
            style={{ ...inputStyle, "--tw-ring-color": COLORS.accent2 }}
          />
          <input
            required
            type="email"
            placeholder="Email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
            className="font-body text-sm rounded-xl px-4 py-3.5 outline-none transition-shadow focus:ring-2"
            style={{ ...inputStyle, "--tw-ring-color": COLORS.accent2 }}
          />
          <textarea
            required
            rows={5}
            placeholder="Message"
            value={form.message}
            onChange={(e) => setForm({ ...form, message: e.target.value })}
            className="font-body text-sm rounded-xl px-4 py-3.5 outline-none resize-none transition-shadow focus:ring-2"
            style={{ ...inputStyle, "--tw-ring-color": COLORS.accent2 }}
          />

          <motion.button
            type="submit"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            className="font-body font-bold text-sm rounded-full px-8 py-3.5 mt-2 self-center"
            style={{ backgroundColor: COLORS.ink, color: "#FFFFFF" }}
          >
            {sent ? "Message sent ✓" : "Send message"}
          </motion.button>
        </motion.form>
      </div>
    </section>
  );
}

