function Footer() {
  return (
    <footer
      className="px-6 py-10 border-t"
      style={{ borderColor: `${COLORS.ink}1A` }}
    >
      <div className="max-w-5xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-6">
        <a
          href="#top"
          onClick={(e) => {
            e.preventDefault();
            const el = document.getElementById("top");
            if (el) el.scrollIntoView({ behavior: "smooth", block: "start" });
          }}
          className="flex items-center"
        >
          <img
            src={LOGO_SRC}
            alt="Sembol Studio logo"
            className="w-auto"
            style={{ height: "48px", width: "auto", maxHeight: "48px" }}
          />
        </a>

        <p
          className="font-body order-3 sm:order-2"
          style={{ color: `${COLORS.ink}80`, fontSize: "14px" }}
        >
          © {new Date().getFullYear()} Sembol Studio. All rights reserved.
        </p>

        <div className="flex gap-3 order-2 sm:order-3">
          <SocialIcon name="pinterest" href={SOCIAL_LINKS.pinterest} />
          <SocialIcon name="instagram" href={SOCIAL_LINKS.instagram} />
          <SocialIcon name="linkedin" href={SOCIAL_LINKS.linkedin} />
        </div>
      </div>
    </footer>
  );
}

/* ---------------------------------------------
   ROOT — page flow: Hero → Portfolio → Services → About → Testimonials → Contact
--------------------------------------------- */
export default function PortfolioSite() {
  const [splashDone, setSplashDone] = useState(false);

  return (
    <>
      <MetaTags />
      {!splashDone && <SplashScreen onDone={() => setSplashDone(true)} />}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: splashDone ? 1 : 0 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
        className="min-h-screen w-full font-body grain"
        style={{ backgroundColor: COLORS.bg }}
      >
        <FontLoader />
        <Header />
        <Hero ready={splashDone} />
        <Portfolio />
        <Services />
        <About />
        <Testimonials />
        <ContactForm />
        <Footer />
      </motion.div>
    </>
  );
}
